  {p : ι → Prop} [DecidablePred p] (f g : ι → M) :
  (∏ x ∈ s, if p x then f x else g x) = (∏ x ∈ s with p x, f x) * ∏ x ∈ s with ¬p x, g x

theorem Finset.sum_apply_ite_of_true.{u_1, u_3, u_5} {ι : Type u_1} {M : Type u_3} {γ : Type u_5}
  {s : Finset ι} [AddCommMonoid M] {p : ι → Prop} [DecidablePred p] (f g : ι → γ) (k : γ → M)
  (h : ∀ x ∈ s, p x) : ∑ x ∈ s, k (if p x then f x else g x) = ∑ x ∈ s, k (f x)

theorem Finset.sum_ite.{u_1, u_3} {ι : Type u_1} {M : Type u_3} [AddCommMonoid M] {s : Finset ι}
  {p : ι → Prop} [DecidablePred p] (f g : ι → M) :
  (∑ x ∈ s, if p x then f x else g x) = ∑ x ∈ s with p x, f x + ∑ x ∈ s with ¬p x, g x

theorem Finset.sum_eq_add_sum_sdiff_singleton_of_mem.{u_1, u_3} {ι : Type u_1} {M : Type u_3}
  [AddCommMonoid M] [DecidableEq ι] {s : Finset ι} {i : ι} (h : i ∈ s) (f : ι → M) :
  ∑ x ∈ s, f x = f i + ∑ x ∈ s \ {i}, f x

theorem Finset.prod_eq_prod_iff_single.{u_1, u_3} {ι : Type u_1} {M : Type u_3} {s : Finset ι}
  [CommMonoid M] [IsRightCancelMul M] {f g : ι → M} {i : ι} (hi : i ∈ s)
  (hfg : ∀ j ∈ s, j ≠ i → f j = g j) : ∏ j ∈ s, f j = ∏ j ∈ s, g j ↔ f i = g i

theorem Set.mulIndicator_eq_mulIndicator.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {M : Type u_3}
  [One M] {s : Set α} {f : α → M} {a : α} {t : Set β} {g : β → M} {b : β} (h1 : a ∈ s ↔ b ∈ t)
  (h2 : f a = g b) : s.mulIndicator f a = t.mulIndicator g b
